package com.alpharip.staffmod.BuildTimelapse.timeline;
import java.util.*;public final class TimelineTrack {private final String id,name;private final List<TimelineClip> clips=new ArrayList<TimelineClip>();public TimelineTrack(String id,String name){if(id==null||name==null)throw new IllegalArgumentException();this.id=id;this.name=name;}public String getId(){return id;}public String getName(){return name;}public synchronized void add(TimelineClip c){if(c==null)throw new IllegalArgumentException();clips.add(c);Collections.sort(clips,new Comparator<TimelineClip>(){public int compare(TimelineClip a,TimelineClip b){return Long.compare(a.getStart(),b.getStart());}});}public synchronized List<TimelineClip> getClips(){return Collections.unmodifiableList(new ArrayList<TimelineClip>(clips));}public synchronized boolean remove(String clipId){for(Iterator<TimelineClip> i=clips.iterator();i.hasNext();)if(i.next().getId().equals(clipId)){i.remove();return true;}return false;}}
